-- Optimized Large Seed Script for FoodExpress (Supabase PostgreSQL Compatible)
-- Seeding 54 restaurants (6 per category across 9 categories) and 540 menu items (10 per restaurant)

-- ==========================================
-- 1. Create Tables
-- ==========================================

CREATE TABLE IF NOT EXISTS user_details (
  u_id SERIAL PRIMARY KEY,
  u_name VARCHAR(100) NOT NULL,
  u_email VARCHAR(100) NOT NULL UNIQUE,
  u_phoneNumber VARCHAR(15) NOT NULL UNIQUE,
  u_address VARCHAR(255) NOT NULL,
  u_password VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS restaurant (
  restaurantId SERIAL PRIMARY KEY,
  restaurantName VARCHAR(100) NOT NULL,
  r_email VARCHAR(100) NOT NULL UNIQUE,
  restaurantPhone VARCHAR(15) NOT NULL UNIQUE,
  r_pass VARCHAR(100) NOT NULL,
  r_type VARCHAR(100) NOT NULL,
  r_address VARCHAR(255) NOT NULL,
  image_url VARCHAR(500)
);

CREATE TABLE IF NOT EXISTS deliverypartner_details (
  dp_id SERIAL PRIMARY KEY,
  dp_name VARCHAR(100) NOT NULL,
  dp_email VARCHAR(100) NOT NULL UNIQUE,
  dp_phoneNumber VARCHAR(15) NOT NULL UNIQUE,
  dp_password VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS menu_item (
  item_id SERIAL PRIMARY KEY,
  item_name VARCHAR(100) NOT NULL,
  price DECIMAL(10,2) NOT NULL,
  r_id INT NOT NULL,
  image_url VARCHAR(500),
  FOREIGN KEY (r_id) REFERENCES restaurant(restaurantId) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS orders (
  order_id SERIAL PRIMARY KEY,
  user_id INT NOT NULL,
  restaurant_id INT NOT NULL,
  delivery_partner_id INT,
  eta_minutes INT,
  total_amount DECIMAL(10,2) NOT NULL,
  status VARCHAR(50) DEFAULT 'PREPARING',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES user_details(u_id) ON DELETE CASCADE,
  FOREIGN KEY (restaurant_id) REFERENCES restaurant(restaurantId) ON DELETE CASCADE,
  FOREIGN KEY (delivery_partner_id) REFERENCES deliverypartner_details(dp_id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS order_items (
  id SERIAL PRIMARY KEY,
  order_id INT NOT NULL,
  item_id INT,
  item_name VARCHAR(100) NOT NULL,
  price DECIMAL(10,2) NOT NULL,
  qty INT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS order_audit (
  id SERIAL PRIMARY KEY,
  order_id INT,
  message VARCHAR(255),
  log_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS menu_audit (
  id SERIAL PRIMARY KEY,
  item_id INT,
  r_id INT,
  message VARCHAR(255),
  log_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS order_history (
  history_id SERIAL PRIMARY KEY,
  order_id INT NOT NULL,
  user_id INT NOT NULL,
  restaurant_id INT NOT NULL,
  delivery_partner_id INT,
  total_amount DECIMAL(10,2) NOT NULL,
  status VARCHAR(50) NOT NULL,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES user_details(u_id) ON DELETE CASCADE,
  FOREIGN KEY (restaurant_id) REFERENCES restaurant(restaurantId) ON DELETE CASCADE,
  FOREIGN KEY (delivery_partner_id) REFERENCES deliverypartner_details(dp_id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS accounts (
  a_id SERIAL PRIMARY KEY,
  cnum BIGINT NOT NULL UNIQUE,
  cvv INT NOT NULL,
  balance DECIMAL(12,2) NOT NULL,
  upi VARCHAR(100) NOT NULL UNIQUE
);

-- Trigger function and Trigger for order_history
CREATE OR REPLACE FUNCTION log_order_history()
RETURNS TRIGGER AS $$
BEGIN
  VALUES (NEW.order_id, NEW.user_id, NEW.restaurant_id, NEW.delivery_partner_id, NEW.total_amount, NEW.status);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_log_order_history ON orders;
CREATE TRIGGER trg_log_order_history
AFTER INSERT OR UPDATE ON orders
FOR EACH ROW
EXECUTE FUNCTION log_order_history();

-- Indexes
CREATE INDEX IF NOT EXISTS idx_orders_restaurant ON orders(restaurant_id);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);

-- Disabling RLS
ALTER TABLE user_details DISABLE ROW LEVEL SECURITY;
ALTER TABLE restaurant DISABLE ROW LEVEL SECURITY;
ALTER TABLE deliverypartner_details DISABLE ROW LEVEL SECURITY;
ALTER TABLE menu_item DISABLE ROW LEVEL SECURITY;
ALTER TABLE orders DISABLE ROW LEVEL SECURITY;
ALTER TABLE order_items DISABLE ROW LEVEL SECURITY;
ALTER TABLE order_audit DISABLE ROW LEVEL SECURITY;
ALTER TABLE menu_audit DISABLE ROW LEVEL SECURITY;
ALTER TABLE accounts DISABLE ROW LEVEL SECURITY;
ALTER TABLE order_history DISABLE ROW LEVEL SECURITY;

-- Clean Data
TRUNCATE TABLE order_history, order_audit, menu_audit, order_items, orders, menu_item, deliverypartner_details, restaurant, user_details, accounts RESTART IDENTITY CASCADE;

