-- 5. Synchronize Sequences
-- ==========================================
SELECT setval(pg_get_serial_sequence('user_details', 'u_id'), COALESCE(MAX(u_id), 1)) FROM user_details;
SELECT setval(pg_get_serial_sequence('restaurant', 'restaurantid'), COALESCE(MAX(restaurantid), 1)) FROM restaurant;
SELECT setval(pg_get_serial_sequence('deliverypartner_details', 'dp_id'), COALESCE(MAX(dp_id), 1)) FROM deliverypartner_details;
SELECT setval(pg_get_serial_sequence('menu_item', 'item_id'), COALESCE(MAX(item_id), 1)) FROM menu_item;
SELECT setval(pg_get_serial_sequence('orders', 'order_id'), COALESCE(MAX(order_id), 1)) FROM orders;
SELECT setval(pg_get_serial_sequence('order_items', 'id'), COALESCE(MAX(id), 1)) FROM order_items;
SELECT setval(pg_get_serial_sequence('order_audit', 'id'), COALESCE(MAX(id), 1)) FROM order_audit;
SELECT setval(pg_get_serial_sequence('menu_audit', 'id'), COALESCE(MAX(id), 1)) FROM menu_audit;
SELECT setval(pg_get_serial_sequence('accounts', 'a_id'), COALESCE(MAX(a_id), 1)) FROM accounts;
SELECT setval(pg_get_serial_sequence('order_history', 'history_id'), COALESCE(MAX(history_id), 1)) FROM order_history;


